def brute_force_search(alphabet_size, max_length, verify):
    def enum(l):
        if l == 0: return [[]]
        return [s + [c] for s in enum(l-1) for c in range(alphabet_size)]
    for l in range(1, max_length + 1):
        for candidate in enum(l):
            if verify(candidate): return candidate
    return None

def info_guided_search(alphabet_size, max_length, prior, verify):
    candidates = []
    def enum(l):
        if l == 0: return [[]]
        return [s + [c] for s in enum(l-1) for c in range(alphabet_size)]
    for l in range(1, max_length + 1):
        for s in enum(l): candidates.append((prior(s), s))
    candidates.sort(key=lambda x: -x[0])
    for _, c in candidates:
        if verify(c): return c
    return None

import math
def proof_length_lower_bound(num_theorems, alphabet_size):
    if num_theorems <= 1: return 0
    return math.ceil(math.log(num_theorems, alphabet_size))
